contracts/super-contributor/LitSuperCont.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

interface ILitSuperContributorNFT is IERC721 {
    function mintFromBridge(address to, uint256 tokenId) external;
    function burnFromBridge(uint256 tokenId) external;
}

contract LitSuperContributorBridge is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    using ECDSA for bytes;

    // Custom storage gap of 250 slots + 1 slot for reentrancy status = 251 slots
    // This aligns sequential variables to start exactly at slot 251 to match the OZ v4 on-chain layout
    uint256[250] private __storageGap;

    uint256 private _reentrancyStatus;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    ILitSuperContributorNFT public nft;
    bool public isHomeChain; // true if Arbitrum (locks/unlocks), false if LitVM (mints/burns)

    address public trustedSigner;
    bool public isPaused;

    // Mapping from message hash (or unique bridge transfer hash) to processed status
    mapping(bytes32 => bool) public processedClaims;

    // Nonce for each user for outbound transfers
    mapping(address => uint256) public userBridgedCount;

    // Mapping to prevent replay attacks on rescue signatures (appended to prevent storage collision)
    mapping(bytes32 => bool) public processedRescues;

    event NFTBridged(
        address indexed user,
        uint256 indexed tokenId,
        uint256 indexed nonce,
        uint256 fromChainId,
        uint256 toChainId
    );

    event NFTClaimed(
        address indexed user,
        uint256 indexed tokenId,
        uint256 indexed nonce,
        uint256 fromChainId,
        uint256 toChainId
    );

    event NFTRescued(
        address indexed user,
        uint256 indexed tokenId,
        uint256 indexed rescueNonce
    );

    event TrustedSignerUpdated(address indexed oldSigner, address indexed newSigner);
    event PauseStatusUpdated(bool paused);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializer function to set up the upgradeable bridge.
     */
    function initialize(
        address _nft,
        bool _isHomeChain,
        address _trustedSigner
    ) external initializer {
        __Ownable_init(msg.sender);
        _reentrancyStatus = _NOT_ENTERED;

        require(_nft != address(0), "Invalid NFT address");
        require(_trustedSigner != address(0), "Invalid signer address");
        nft = ILitSuperContributorNFT(_nft);
        isHomeChain = _isHomeChain;
        trustedSigner = _trustedSigner;
    }

    modifier nonReentrant() {
        require(_reentrancyStatus != _ENTERED, "ReentrancyGuard: reentrant call");
        _reentrancyStatus = _ENTERED;
        _;
        _reentrancyStatus = _NOT_ENTERED;
    }

    modifier whenNotPaused() {
        require(!isPaused, "Bridge is paused");
        _;
    }

    /**
     * @notice Initiates a bridge transfer of an NFT.
     * @param tokenId The ID of the NFT to bridge.
     * @param targetChainId The destination chain ID (e.g. 4441 or 42161).
     */
    function bridgeNFT(uint256 tokenId, uint256 targetChainId) external nonReentrant whenNotPaused {
        require(nft.ownerOf(tokenId) == msg.sender, "Not the owner of the token");

        uint256 nonce = userBridgedCount[msg.sender];
        userBridgedCount[msg.sender] = nonce + 1;

        if (isHomeChain) {
            // Lock NFT on Arbitrum (transfers to this bridge contract)
            nft.transferFrom(msg.sender, address(this), tokenId);
        } else {
            // Burn NFT on LitVM
            nft.burnFromBridge(tokenId);
        }

        emit NFTBridged(msg.sender, tokenId, nonce, block.chainid, targetChainId);
    }

    /**
     * @notice Claims a bridged NFT on the destination chain.
     * @param user The receiver of the NFT.
     * @param tokenId The token ID.
     * @param sourceChainId The chain ID where the transfer was initiated.
     * @param nonce The nonce from the source transfer.
     * @param signature Cryptographic signature authorizing the claim.
     */
    function claimNFT(
        address user,
        uint256 tokenId,
        uint256 sourceChainId,
        uint256 nonce,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        bytes32 messageHash = getClaimHash(user, tokenId, sourceChainId, block.chainid, nonce);
        require(!processedClaims[messageHash], "Claim already processed");

        bytes32 ethHash = MessageHashUtils.toEthSignedMessageHash(messageHash);
        address recovered = ECDSA.recover(ethHash, signature);
        require(recovered == trustedSigner, "Invalid signature");

        processedClaims[messageHash] = true;

        if (isHomeChain) {
            // Unlock on Arbitrum: transfer from this bridge to the user
            nft.transferFrom(address(this), user, tokenId);
        } else {
            // Mint on LitVM: call the special mint function
            nft.mintFromBridge(user, tokenId);
        }

        emit NFTClaimed(user, tokenId, nonce, sourceChainId, block.chainid);
    }

    /**
     * @notice Generates the message hash that the trusted signer must sign.
     */
    function getClaimHash(
        address user,
        uint256 tokenId,
        uint256 sourceChainId,
        uint256 targetChainId,
        uint256 nonce
    ) public view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                address(this),
                user,
                tokenId,
                sourceChainId,
                targetChainId,
                nonce
            )
        );
    }

    /**
     * @notice Allows a user to rescue a stuck NFT with a specific rescue signature from the trusted signer.
     * @param tokenId The ID of the NFT to rescue.
     * @param rescueNonce A unique nonce for the rescue request to prevent replay attacks.
     * @param signature Cryptographic signature from the trusted signer authorizing the rescue.
     */
    function rescueNFT(
        uint256 tokenId,
        uint256 rescueNonce,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        bytes32 rescueHash = getRescueHash(msg.sender, tokenId, block.chainid, rescueNonce);
        require(!processedRescues[rescueHash], "Rescue already processed");

        bytes32 ethHash = MessageHashUtils.toEthSignedMessageHash(rescueHash);
        address recovered = ECDSA.recover(ethHash, signature);
        require(recovered == trustedSigner, "Invalid signature");

        processedRescues[rescueHash] = true;

        if (isHomeChain) {
            // Transfer locked NFT from this bridge to the user
            nft.transferFrom(address(this), msg.sender, tokenId);
        } else {
            // Mint NFT to the user
            nft.mintFromBridge(msg.sender, tokenId);
        }

        emit NFTRescued(msg.sender, tokenId, rescueNonce);
    }

    /**
     * @notice Generates the message hash that the trusted signer must sign for rescues.
     */
    function getRescueHash(
        address user,
        uint256 tokenId,
        uint256 targetChainId,
        uint256 rescueNonce
    ) public view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                "RESCUE",
                address(this),
                user,
                tokenId,
                targetChainId,
                rescueNonce
            )
        );
    }

    // ==================== ADMIN FUNCTIONS ====================

    function setTrustedSigner(address _trustedSigner) external onlyOwner {
        require(_trustedSigner != address(0), "Invalid signer address");
        address oldSigner = trustedSigner;
        trustedSigner = _trustedSigner;
        emit TrustedSignerUpdated(oldSigner, _trustedSigner);
    }

    function setPaused(bool _paused) external onlyOwner {
        isPaused = _paused;
        emit PauseStatusUpdated(_paused);
    }

    // Emergency withdrawal in case any NFTs or ETH get stuck (owner only)
    function emergencyWithdrawNFT(address tokenAddress, uint256 tokenId, address to) external onlyOwner {
        IERC721(tokenAddress).transferFrom(address(this), to, tokenId);
    }

    // Emergency withdrawal of ETH (owner only)
    function emergencyWithdrawETH(address payable to) external onlyOwner {
        (bool success, ) = to.call{value: address(this).balance}("");
        require(success, "Withdraw failed");
    }

    /**
     * @dev Required override for UUPS upgrade authorization.
     */
    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

/**
 * @title LitSuperContributorNFT
 * @dev Upgradeable ERC721 NFT contract for Athes Super Contributor (LSC) on Arbitrum.
 * Features customizable claim price, base URI, total supply caps, and admin controls.
 * Uses UUPS pattern for gas-efficient upgrades.
 * Includes support for non-transferable (soulbound) NFTs with admin toggle,
 * automatic payment forwarding for mints, and ERC2981 royalty implementation.
 */
contract LitSuperContributorNFT is
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    using Strings for uint256;

    // Inline reentrancy guard (OZ v5 contracts-upgradeable has no ReentrancyGuardUpgradeable)
    uint256 private _reentrancyStatus;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    modifier nonReentrant() {
        require(_reentrancyStatus != _ENTERED, "ReentrancyGuard: reentrant call");
        _reentrancyStatus = _ENTERED;
        _;
        _reentrancyStatus = _NOT_ENTERED;
    }

    // State Variables
    uint256 public claimPrice;
    uint256 public maxSupply;
    uint256 public totalMinted;
    string private _baseTokenURI;

    // Upgraded State Variables (appended at the end to prevent storage collision)
    bool public transfersEnabled;
    address public paymentReceiver;
    uint96 public royaltyFeeNumerator;
    // DEPRECATED (kept for storage slot compatibility) - use authorizedBridges mapping instead
    address public bridgeAddress;

    // FIX: Support multiple authorized bridge/staking addresses (slot added after bridgeAddress)
    mapping(address => bool) public authorizedBridges;

    // Events
    event ClaimPriceUpdated(uint256 newPrice);
    event BaseURIUpdated(string newBaseURI);
    event MaxSupplyUpdated(uint256 newMaxSupply);
    event NFTClaimed(address indexed claimer, uint256 indexed tokenId, uint256 pricePaid);
    event FundsWithdrawn(address indexed owner, uint256 amount);
    event TransfersEnabledUpdated(bool enabled);
    event PaymentReceiverUpdated(address indexed newReceiver);
    event RoyaltyFeeNumeratorUpdated(uint96 newNumerator);
    event BridgeAddressUpdated(address indexed newBridge);
    event AuthorizedBridgeUpdated(address indexed bridge, bool authorized);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @dev Initializer function to set up the upgradeable contract.
     * Replaces the constructor.
     */
    function initialize(
        string memory name_,
        string memory symbol_,
        string memory baseURI_,
        uint256 maxSupply_,
        uint256 claimPrice_
    ) external initializer {
        __ERC721_init(name_, symbol_);
        __Ownable_init(msg.sender);
        _reentrancyStatus = _NOT_ENTERED;

        claimPrice = claimPrice_;
        maxSupply = maxSupply_;
        _baseTokenURI = baseURI_;
    }

    /**
     * @dev Claim function allows users to mint a Athes Super Contributor NFT.
     * Must send the exact claim price.
     * Payments are automatically forwarded to the payment receiver.
     */
    function claim() external payable nonReentrant {
        require(claimPrice > 0, "Claiming is disabled");
        require(msg.value >= claimPrice, "Insufficient payment");
        require(totalMinted < maxSupply, "Max supply reached");

        uint256 tokenId = totalMinted + 1;
        totalMinted++;

        _safeMint(msg.sender, tokenId);

        emit NFTClaimed(msg.sender, tokenId, msg.value);

        // Forward claim payment automatically to the receiver
        address receiver = paymentReceiver == address(0)
            ? 0x48234eD645676b794a4CbC7483513e58cB04e22E
            : paymentReceiver;
        (bool paymentSuccess, ) = payable(receiver).call{value: claimPrice}("");
        require(paymentSuccess, "Payment transfer failed");

        // Refund excess ether if any is sent
        if (msg.value > claimPrice) {
            uint256 excess = msg.value - claimPrice;
            (bool refundSuccess, ) = payable(msg.sender).call{value: excess}("");
            require(refundSuccess, "Refund failed");
        }
    }

    /**
     * @dev Claim function allows users to mint multiple Athes Super Contributor NFTs in a single transaction.
     * Must send at least (claimPrice * quantity) in msg.value.
     * Payments are automatically forwarded to the payment receiver.
     */
    function claimBatch(uint256 quantity) external payable nonReentrant {
        require(quantity > 0, "Quantity must be greater than 0");
        require(claimPrice > 0, "Claiming is disabled");
        uint256 totalCost = claimPrice * quantity;
        require(msg.value >= totalCost, "Insufficient payment");
        require(totalMinted + quantity <= maxSupply, "Exceeds max supply");

        for (uint256 i = 0; i < quantity; i++) {
            uint256 tokenId = totalMinted + 1;
            totalMinted++;
            _safeMint(msg.sender, tokenId);
            emit NFTClaimed(msg.sender, tokenId, claimPrice);
        }

        // Forward claim payment automatically to the receiver
        address receiver = paymentReceiver == address(0)
            ? 0x48234eD645676b794a4CbC7483513e58cB04e22E
            : paymentReceiver;
        (bool paymentSuccess, ) = payable(receiver).call{value: totalCost}("");
        require(paymentSuccess, "Payment transfer failed");

        // Refund excess ether if any is sent
        if (msg.value > totalCost) {
            uint256 excess = msg.value - totalCost;
            (bool refundSuccess, ) = payable(msg.sender).call{value: excess}("");
            require(refundSuccess, "Refund failed");
        }
    }

    /**
     * @dev Admin/owner mint function for promo, seed, or direct allocations.
     */
    function adminMint(address to, uint256 quantity) external onlyOwner {
        require(totalMinted + quantity <= maxSupply, "Exceeds max supply");
        for (uint256 i = 0; i < quantity; i++) {
            uint256 tokenId = totalMinted + 1;
            totalMinted++;
            _safeMint(to, tokenId);
        }
    }

    /**
     * @dev Update the claim price.
     */
    function setClaimPrice(uint256 newPrice) external onlyOwner {
        claimPrice = newPrice;
        emit ClaimPriceUpdated(newPrice);
    }

    /**
